BOARD_NAME_ALIASES: dict[str, str] = {}


def get_target_database_summary() -> dict[str, Any]:
    """Return generated target database coverage metadata."""
    return copy.deepcopy(TARGET_DATABASE_SUMMARY)


def get_target_overlay(
    board_name: str | None,
    manufacturer_id: str | None = None,
) -> dict[str, Any] | None:
    """Look up a target overlay by exact target name.

    Matching is case-insensitive but not fuzzy. Manufacturer mismatch does not
    hide an otherwise exact board match; it lowers confidence and adds a
    warning so runtime code cannot overstate firmware_plus_target proof.
    """
    if not board_name:
        return None
    key = str(board_name).strip().upper()
    canonical = key if key in TARGET_OVERLAYS else BOARD_NAME_ALIASES.get(key)
    if not canonical or canonical not in TARGET_OVERLAYS:
        return None
    overlay = copy.deepcopy(TARGET_OVERLAYS[canonical])
    expected = str(overlay.get("manufacturer_id") or "").strip().upper()
    supplied = str(manufacturer_id or "").strip().upper()
    if supplied and expected and supplied != expected:
        overlay["target_match_status"] = "manufacturer_mismatch"
        overlay["target_match_confidence"] = "medium"
        overlay.setdefault("warnings", []).append("manufacturer_id_mismatch")
        overlay.setdefault("hardware_config", {}).setdefault("warnings", []).append("manufacturer_id_mismatch")
    elif supplied and expected == supplied:
        overlay["target_match_status"] = "verified"
        overlay["target_match_confidence"] = "high"
    else:
        overlay["target_match_status"] = "verified"
        overlay["target_match_confidence"] = "medium"
    return overlay


__all__ = [
    "BOARD_NAME_ALIASES",
    "TARGET_DATABASE_SUMMARY",
    "TARGET_OVERLAYS",
    "get_target_database_summary",
    "get_target_overlay",
]
